/**
 * Client for the FX provider exposed through the Named Credential `FB_Exchange_Rates`.
 *
 * Usage:
 *   Map<String, Decimal> rates = ExchangeRateClient.getRates('eur', new Set<String>{ 'usd', 'gbp' });
 *
 * All input currency codes are normalised (trimmed + upper-cased) and validated before any
 * callout is made. Any problem (invalid input, non-200 status, unparseable body, missing rate)
 * is surfaced as the inner `ExchangeRateException`.
 */
public with sharing class ExchangeRateClient {

    /** Endpoint supplied by the Named Credential (auth + base URL live there). */
    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    /** HTTP status that triggers a single retry. */
    private static final Integer RETRY_STATUS = 503;

    private static final Integer SUCCESS_STATUS = 200;
    private static final Integer MAX_ATTEMPTS = 2;

    /** Raised for invalid input, callout failures, unexpected statuses or bad payloads. */
    public class ExchangeRateException extends Exception {}

    /**
     * Fetches the latest rates for the requested quote currencies against a base currency.
     *
     * @param baseCurrency   Base currency code (e.g. 'EUR'), normalised and validated.
     * @param quoteCurrencies Quote currency codes (e.g. {'USD','GBP'}), normalised and validated.
     * @return Map of every requested normalised code to its rate. Extra rates in the
     *         response are ignored.
     * @throws ExchangeRateException if input is invalid (before any callout), the callout fails,
     *         the final status is not 200, the body cannot be parsed, or a requested code
     *         has no rate.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // ---- 1. Validate / normalise everything BEFORE any callout -------------------------
        String base = normalise(baseCurrency, 'base');

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        Set<String> normalisedQuotes = new Set<String>();
        for (String code : quoteCurrencies) {
            normalisedQuotes.add(normalise(code, 'quote'));
        }

        List<String> quotes = new List<String>(normalisedQuotes);
        quotes.sort();

        // ---- 2. One request per call, plus a single retry on 503 ---------------------------
        HttpResponse response = send(buildRequest(base, quotes));
        if (response.getStatusCode() == RETRY_STATUS && MAX_ATTEMPTS > 1) {
            response = send(buildRequest(base, quotes));
        }

        Integer status = response.getStatusCode();
        if (status != SUCCESS_STATUS) {
            throw new ExchangeRateException(
                'FX provider callout failed with HTTP status code ' + status + '.'
            );
        }

        // ---- 3. Parse and map the requested codes ------------------------------------------
        Map<String, Object> rates = readRates(response.getBody());

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : quotes) {
            Object raw = rates == null ? null : rates.get(code);
            if (raw == null) {
                throw new ExchangeRateException('No rate returned for currency ' + code + '.');
            }
            Decimal rate;
            try {
                rate = toDecimal(raw);
            } catch (Exception e) {
                throw new ExchangeRateException(
                    'Rate returned for currency ' + code + ' is not numeric.'
                );
            }
            result.put(code, rate);
        }
        return result;
    }

    // ---------------------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------------------

    /** Trims, upper-cases and validates a single currency code (exactly three letters A-Z). */
    private static String normalise(String code, String label) {
        String value = (code == null) ? '' : code.trim().toUpperCase();
        if (!isThreeLetterCode(value)) {
            throw new ExchangeRateException(
                'Invalid ' + label + ' currency code: "' + String.valueOf(code) +
                '". Expected exactly three letters A-Z.'
            );
        }
        return value;
    }

    /** True only if the string is exactly three characters, each in the range 'A'..'Z'. */
    private static Boolean isThreeLetterCode(String value) {
        if (value == null || value.length() != 3) {
            return false;
        }
        for (Integer i = 0; i < value.length(); i++) {
            Integer codePoint = value.charAt(i);
            // 'A' = 65, 'Z' = 90
            if (codePoint < 65 || codePoint > 90) {
                return false;
            }
        }
        return true;
    }

    /** Builds the identical GET request used for both the initial attempt and the retry. */
    private static HttpRequest buildRequest(String base, List<String> quotes) {
        String symbols = String.join(quotes, ',');

        HttpRequest request = new HttpRequest();
        request.setEndpoint(
            ENDPOINT +
            '?base=' + EncodingUtil.urlEncode(base, 'UTF-8') +
            '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8')
        );
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        // Authentication is supplied by the Named Credential - never set it here.
        return request;
    }

    /** Executes the request; transport problems are wrapped in the public exception. */
    private static HttpResponse send(HttpRequest request) {
        try {
            return new Http().send(request);
        } catch (Exception e) {
            throw new ExchangeRateException('Callout to the FX provider failed: ' + e.getMessage());
        }
    }

    /** Parses the response body and returns the `rates` object. */
    private static Map<String, Object> readRates(String body) {
        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse the FX response body: ' + e.getMessage());
        }

        Map<String, Object> rootMap;
        try {
            rootMap = (Map<String, Object>) root;
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse the FX response body: expected a JSON object.');
        }
        if (rootMap == null) {
            throw new ExchangeRateException('Unable to parse the FX response body: expected a JSON object.');
        }

        Object ratesObject = rootMap.get('rates');
        if (ratesObject == null) {
            throw new ExchangeRateException('Unable to parse the FX response body: no "rates" object found.');
        }

        Map<String, Object> rates;
        try {
            rates = (Map<String, Object>) ratesObject;
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse the FX response body: "rates" is not a JSON object.');
        }
        return rates;
    }

    /** Converts a JSON value (number or numeric string) to Decimal. */
    private static Decimal toDecimal(Object value) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof String) {
            return Decimal.valueOf(((String) value).trim());
        }
        return Decimal.valueOf(String.valueOf(value));
    }
}
