/**
 * Server side service used by the "record finder" Lightning component.
 *
 * The class validates the requested object/field API names (case-insensitively),
 * enforces object- and field-level security for every field involved, builds a
 * single dynamic SOQL statement using bind variables (so filter values coming
 * from the UI can never inject SOQL) and executes it in user mode so that the
 * running user's sharing rules and field-level security are always respected.
 */
public with sharing class RecordSearchService {

    /** The only exception type this service ever throws. */
    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    /**
     * Runs a single equality-filtered SOQL query against any readable object.
     *
     * @param objectApiName API name of the object to search (case-insensitive).
     * @param fields        API names of the fields to select (case-insensitive).
     * @param filters       Map of field API name -> value; each entry becomes one
     *                      `field = value` condition combined with AND. May be null/empty.
     * @param orderByField  Optional API name of the field to sort on (ascending).
     * @param maxRows       Number of rows to return, must be 1..200.
     * @return The matching records (sharing and FLS enforced).
     * @throws SearchException if any validation fails.
     */
    public static List<SObject> search(String objectApiName, List<String> fields,
            Map<String, Object> filters, String orderByField, Integer maxRows) {

        // --- maxRows validation -------------------------------------------------
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.');
        }

        // --- object validation (case-insensitive, must be readable) -------------
        Schema.DescribeSObjectResult objectDescribe = describeObject(objectApiName);
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('You do not have read access to the object '
                + objectDescribe.getName() + '.');
        }

        // --- selected fields ----------------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        List<String> selectFields = new List<String>();
        Set<String> alreadySelected = new Set<String>();
        for (String requestedField : fields) {
            Schema.DescribeFieldResult fieldDescribe = describeField(fieldMap, requestedField);
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to the field '
                    + fieldDescribe.getName() + '.');
            }
            String lowerName = fieldDescribe.getName().toLowerCase();
            if (!alreadySelected.contains(lowerName)) {
                alreadySelected.add(lowerName);
                selectFields.add(fieldDescribe.getName());
            }
        }

        // --- filter conditions --------------------------------------------------
        List<String> conditions = new List<String>();
        Map<String, Object> bindValues = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String requestedFilter : filters.keySet()) {
                Schema.DescribeFieldResult fieldDescribe = describeField(fieldMap, requestedFilter);
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('You do not have read access to the field '
                        + fieldDescribe.getName() + '.');
                }
                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException('The field ' + fieldDescribe.getName()
                        + ' cannot be used in a filter.');
                }
                Object filterValue = filters.get(requestedFilter);
                if (filterValue == null) {
                    // No user data is written into the statement, so this is injection safe.
                    conditions.add(fieldDescribe.getName() + ' = null');
                } else {
                    // Bind variables make the value immune to SOQL injection regardless of type.
                    String bindName = 'v' + bindIndex;
                    bindIndex++;
                    conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                    bindValues.put(bindName, filterValue);
                }
            }
        }

        // --- order by -----------------------------------------------------------
        String orderClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult fieldDescribe = describeField(fieldMap, orderByField);
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to the field '
                    + fieldDescribe.getName() + '.');
            }
            if (!fieldDescribe.isSortable()) {
                throw new SearchException('The field ' + fieldDescribe.getName()
                    + ' cannot be used to sort the results.');
            }
            orderClause = ' ORDER BY ' + fieldDescribe.getName() + ' ASC';
        }

        // --- build the single SOQL statement -------------------------------------
        String soql = 'SELECT Id';
        for (String fieldName : selectFields) {
            if (!fieldName.equalsIgnoreCase('Id')) {
                soql += ', ' + fieldName;
            }
        }
        soql += ' FROM ' + objectDescribe.getName();
        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        soql += orderClause;
        soql += ' LIMIT ' + maxRows;

        try {
            // USER_MODE re-enforces object/field-level security and sharing at runtime.
            return Database.queryWithBinds(soql, bindValues, AccessLevel.USER_MODE);
        } catch (Exception ex) {
            // Never leak an unexpected exception type to the caller.
            throw new SearchException('The search could not be executed: ' + ex.getMessage());
        }
    }

    /**
     * Resolves an object API name case-insensitively.
     *
     * @throws SearchException when the object does not exist.
     */
    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType token = globalDescribe.get(objectApiName);
        if (token == null) {
            String lowerName = objectApiName.toLowerCase();
            for (String key : globalDescribe.keySet()) {
                if (key.toLowerCase().equals(lowerName)) {
                    token = globalDescribe.get(key);
                    break;
                }
            }
        }
        if (token == null) {
            throw new SearchException('The object ' + objectApiName + ' does not exist.');
        }
        return token.getDescribe();
    }

    /**
     * Resolves a field API name case-insensitively against a field map.
     *
     * @throws SearchException when the name is blank or is not a field of the object.
     */
    private static Schema.DescribeFieldResult describeField(
            Map<String, Schema.SObjectField> fieldMap, String fieldApiName) {
        if (String.isBlank(fieldApiName)) {
            throw new SearchException('A field API name is required.');
        }
        Schema.SObjectField token = fieldMap.get(fieldApiName);
        if (token == null) {
            String lowerName = fieldApiName.toLowerCase();
            for (String key : fieldMap.keySet()) {
                if (key.toLowerCase().equals(lowerName)) {
                    token = fieldMap.get(key);
                    break;
                }
            }
        }
        if (token == null) {
            throw new SearchException('The field ' + fieldApiName + ' does not exist.');
        }
        return token.getDescribe();
    }
}
