/**
 * Tests for OpportunityTrigger and OpportunityWonHandler.
 *
 * Documented behaviour covered:
 *  - An opportunity that is inserted with StageName 'Closed Won' is "newly won": NextStep is set
 *    to 'Handover to Customer Success' before the record is saved, exactly one Task
 *    ('Customer kick-off', WhatId = the opportunity, OwnerId = the opportunity owner,
 *    ActivityDate = CloseDate + 7 days, Priority 'High') is created and the account (if any) is
 *    re-rated 'Hot'.
 *  - An opportunity updated from any other stage to 'Closed Won' gets the same treatment.
 *  - Every other insert or update (insert of a non-won opportunity, an edit to an opportunity that
 *    was already won, an update that leaves Closed Won) changes nothing.
 *  - Accounts already rated 'Hot' are not updated again.
 *  - Bulk safety: at most one SOQL query (and therefore at most three DML statements: opportunities
 *    + tasks + accounts) per trigger execution for up to 200 records.
 *
 * NOTE: local variables are deliberately named so that they never shadow the class constants
 * (Apex identifiers are case-insensitive), e.g. `hotAcct` instead of `hot`.
 */
@IsTest
private class OpportunityWonHandlerTest {

    private static final String WON = 'Closed Won';
    private static final String LOST = 'Closed Lost';
    private static final String PROSPECTING = 'Prospecting';
    private static final String HANDOVER = 'Handover to Customer Success';
    private static final String KICK_OFF = 'Customer kick-off';
    private static final String HIGH = 'High';
    private static final String HOT = 'Hot';
    private static final String WARM = 'Warm';
    private static final String COLD = 'Cold';

    /* ------------------------------------------------------------------ */
    /* helpers                                                            */
    /* ------------------------------------------------------------------ */

    private static Account makeAccount(String rating) {
        return new Account(Name = 'Test Account', Rating = rating);
    }

    private static Opportunity makeOpportunity(String name, String stage, Date closeDate, Id accountId) {
        Opportunity opp = new Opportunity(Name = name, StageName = stage, CloseDate = closeDate);
        if (accountId != null) {
            opp.AccountId = accountId;
        }
        return opp;
    }

    private static Set<Id> idsOf(List<Opportunity> opps) {
        Set<Id> result = new Set<Id>();
        for (Opportunity opp : opps) {
            result.add(opp.Id);
        }
        return result;
    }

    private static List<Task> tasksFor(Set<Id> oppIds) {
        return [
            SELECT Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId IN :oppIds
        ];
    }

    private static String nextStepOf(Id oppId) {
        return [SELECT NextStep FROM Opportunity WHERE Id = :oppId].NextStep;
    }

    private static String ratingOf(Id accountId) {
        return [SELECT Rating FROM Account WHERE Id = :accountId].Rating;
    }

    /* ------------------------------------------------------------------ */
    /* insert as Closed Won                                               */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void insertClosedWonAppliesFullHandover() {
        Account acct = makeAccount(WARM);
        insert acct;

        Opportunity opp = makeOpportunity('Won on insert', WON, Date.newInstance(2025, 1, 31), acct.Id);
        opp.NextStep = 'To be replaced';

        insert opp;

        Opportunity saved = [SELECT NextStep, OwnerId FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(HANDOVER, saved.NextStep,
            'An opportunity inserted with StageName Closed Won must get NextStep "' + HANDOVER + '".');

        List<Task> tasks = tasksFor(new Set<Id>{ opp.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        Task created = tasks[0];
        System.assertEquals(KICK_OFF, created.Subject, 'The task subject must be "Customer kick-off".');
        System.assertEquals(opp.Id, created.WhatId, 'The task must be linked to the opportunity.');
        System.assertEquals(saved.OwnerId, created.OwnerId, 'The task must be owned by the opportunity owner.');
        System.assertEquals(HIGH, created.Priority, 'The task priority must be High.');
        System.assertEquals(Date.newInstance(2025, 2, 7), created.ActivityDate,
            'ActivityDate must be CloseDate + 7 days, including across a month boundary.');

        System.assertEquals(HOT, ratingOf(acct.Id), 'The account must be re-rated Hot.');
    }

    @IsTest
    static void insertClosedWonWithoutAccountStillGetsHandover() {
        Opportunity opp = makeOpportunity('Won on insert, no account', WON,
            Date.newInstance(2025, 9, 9), null);

        insert opp;

        System.assertEquals(HANDOVER, nextStepOf(opp.Id),
            'NextStep must be set even when the opportunity has no account.');

        List<Task> tasks = tasksFor(new Set<Id>{ opp.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        System.assertEquals(opp.Id, tasks[0].WhatId, 'The task must be linked to the opportunity.');
        System.assertEquals(HIGH, tasks[0].Priority, 'The task priority must be High.');
        System.assertEquals(Date.newInstance(2025, 9, 16), tasks[0].ActivityDate,
            'ActivityDate must be CloseDate + 7 days.');
    }

    @IsTest
    static void taskIsOwnedByTheOpportunityOwner() {
        Profile stdProfile = [SELECT Id FROM Profile WHERE UserType = 'Standard' LIMIT 1];
        String uniqueSuffix = EncodingUtil.convertToHex(Crypto.generateAesKey(128)).substring(0, 12);
        User otherUser = new User(
            Alias = 'handovr',
            Email = 'handover.owner.' + uniqueSuffix + '@example.test',
            EmailEncodingKey = 'UTF-8',
            LastName = 'Handover Owner',
            LanguageLocaleKey = 'en_US',
            LocaleSidKey = 'en_US',
            ProfileId = stdProfile.Id,
            TimeZoneSidKey = 'America/Los_Angeles',
            Username = 'handover.owner.' + uniqueSuffix + '@example.test'
        );
        insert otherUser;

        Opportunity opp = makeOpportunity('Owned by somebody else', WON, Date.newInstance(2025, 5, 16), null);
        opp.OwnerId = otherUser.Id;
        insert opp;

        Opportunity saved = [SELECT OwnerId FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(otherUser.Id, saved.OwnerId,
            'Sanity check: the opportunity really is owned by the other user.');

        List<Task> tasks = tasksFor(new Set<Id>{ opp.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        System.assertEquals(otherUser.Id, tasks[0].OwnerId,
            'The kick-off task must be owned by the opportunity owner, not by the running user.');
    }

    /* ------------------------------------------------------------------ */
    /* insert that is not a win                                           */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void insertThatIsNotWonChangesNothing() {
        Account acctA = makeAccount(WARM);
        Account acctB = makeAccount(COLD);
        insert new List<Account>{ acctA, acctB };

        Opportunity openOpp = makeOpportunity('Still open', PROSPECTING,
            Date.newInstance(2025, 5, 9), acctA.Id);
        openOpp.NextStep = 'Left alone - open';
        Opportunity lostOpp = makeOpportunity('Lost on insert', LOST,
            Date.newInstance(2025, 5, 10), acctB.Id);
        lostOpp.NextStep = 'Left alone - lost';

        insert new List<Opportunity>{ lostOpp, openOpp };

        System.assertEquals('Left alone - open', nextStepOf(openOpp.Id),
            'NextStep must not be overwritten for an opportunity that is not Closed Won.');
        System.assertEquals('Left alone - lost', nextStepOf(lostOpp.Id),
            'NextStep must not be overwritten for a lost opportunity.');

        System.assertEquals(0, tasksFor(new Set<Id>{ openOpp.Id, lostOpp.Id }).size(),
            'No task may be created for a non-won insert.');

        System.assertEquals(WARM, ratingOf(acctA.Id),
            'The account of a non-won opportunity must not be re-rated.');
        System.assertEquals(COLD, ratingOf(acctB.Id),
            'The account of a lost opportunity must not be re-rated.');
    }

    /* ------------------------------------------------------------------ */
    /* update to Closed Won                                               */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void updateToClosedWonAppliesFullHandover() {
        Account acct = makeAccount(COLD);
        insert acct;

        Opportunity opp = makeOpportunity('Won on update', PROSPECTING,
            Date.newInstance(2024, 12, 30), acct.Id);
        opp.NextStep = 'Not handed over yet';
        insert opp;
        System.assertEquals(0, tasksFor(new Set<Id>{ opp.Id }).size(),
            'No task exists before the opportunity is won.');
        System.assertEquals(COLD, ratingOf(acct.Id),
            'Sanity check: the account is still Cold before the win.');

        opp.StageName = WON;
        opp.NextStep = 'Should be replaced';

        update opp;

        System.assertEquals(HANDOVER, nextStepOf(opp.Id),
            'NextStep must be set when the stage changes to Closed Won.');

        List<Task> tasks = tasksFor(new Set<Id>{ opp.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        Task created = tasks[0];
        System.assertEquals(KICK_OFF, created.Subject, 'The task subject must be "Customer kick-off".');
        System.assertEquals(opp.Id, created.WhatId, 'The task must be linked to the opportunity.');
        System.assertEquals(HIGH, created.Priority, 'The task priority must be High.');
        System.assertEquals(Date.newInstance(2025, 1, 6), created.ActivityDate,
            'ActivityDate must be CloseDate + 7 days, including across a year boundary.');

        Opportunity saved = [SELECT OwnerId FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(saved.OwnerId, created.OwnerId,
            'The task must be owned by the opportunity owner.');

        System.assertEquals(HOT, ratingOf(acct.Id), 'The account must be re-rated Hot.');
    }

    /* ------------------------------------------------------------------ */
    /* updates that change nothing                                        */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void updateOnAlreadyWonOpportunityChangesNothing() {
        Account acct = makeAccount(WARM);
        insert acct;

        Opportunity opp = makeOpportunity('Already won', WON, Date.newInstance(2025, 6, 2), acct.Id);
        insert opp;
        System.assertEquals(1, tasksFor(new Set<Id>{ opp.Id }).size(),
            'The initial win created exactly one task.');
        System.assertEquals(HANDOVER, nextStepOf(opp.Id), 'Sanity check: the handover text was written.');
        System.assertEquals(HOT, ratingOf(acct.Id), 'Sanity check: the account was re-rated.');

        opp.NextStep = 'Renegotiated next step';
        opp.CloseDate = Date.newInstance(2025, 7, 2);
        update opp;

        System.assertEquals('Renegotiated next step', nextStepOf(opp.Id),
            'Editing an opportunity that is already won must not overwrite NextStep.');
        System.assertEquals(1, tasksFor(new Set<Id>{ opp.Id }).size(),
            'No second kick-off task may be created for an already-won opportunity.');
        System.assertEquals(HOT, ratingOf(acct.Id), 'The account rating must remain Hot.');
    }

    @IsTest
    static void updateFromClosedWonToClosedLostChangesNothing() {
        Account acct = makeAccount(WARM);
        insert acct;

        Opportunity opp = makeOpportunity('Losing it', WON, Date.newInstance(2025, 4, 10), acct.Id);
        insert opp;
        System.assertEquals(1, tasksFor(new Set<Id>{ opp.Id }).size(),
            'The initial win created exactly one task.');
        System.assertEquals(HOT, ratingOf(acct.Id), 'Sanity check: the account was re-rated.');

        opp.StageName = LOST;
        opp.NextStep = 'Back with sales';
        update opp;

        System.assertEquals('Back with sales', nextStepOf(opp.Id),
            'An update that leaves Closed Won must not write the handover text.');
        System.assertEquals(1, tasksFor(new Set<Id>{ opp.Id }).size(),
            'An update that leaves Closed Won must not create another task.');
        System.assertEquals(HOT, ratingOf(acct.Id), 'The account rating must stay Hot.');
    }

    @IsTest
    static void updateWithNoNewlyWonRecordDoesNoExtraWork() {
        Account acct = makeAccount(WARM);
        insert acct;

        Opportunity opp = makeOpportunity('Never won', PROSPECTING, Date.newInstance(2025, 10, 1), acct.Id);
        opp.NextStep = 'Original next step';
        insert opp;

        Integer dmlBefore = Limits.getDmlStatements();
        Integer soqlBefore = Limits.getQueries();

        // Still not Closed Won after the edit.
        opp.StageName = LOST;
        opp.NextStep = 'Changed next step';
        update opp;

        Integer dmlUsed = Limits.getDmlStatements() - dmlBefore;
        Integer soqlUsed = Limits.getQueries() - soqlBefore;

        System.assertEquals(1, dmlUsed,
            'Only the opportunity itself may be updated when no record becomes newly won; '
            + 'DML statements used: ' + dmlUsed + '.');
        System.assertEquals(0, soqlUsed,
            'No SOQL may run when no record becomes newly won; SOQL queries used: ' + soqlUsed + '.');

        System.assertEquals('Changed next step', nextStepOf(opp.Id),
            'The NextStep entered by the user must be preserved.');
        System.assertEquals(0, tasksFor(new Set<Id>{ opp.Id }).size(),
            'No task may be created when no record becomes newly won.');
        System.assertEquals(WARM, ratingOf(acct.Id),
            'The account must not be re-rated when no record becomes newly won.');
    }

    /* ------------------------------------------------------------------ */
    /* mixed batches                                                      */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void mixedInsertOnlyHandoversTheWonRecord() {
        Account wonAcct = makeAccount(WARM);
        Account openAcct = makeAccount(WARM);
        insert new List<Account>{ wonAcct, openAcct };

        Opportunity openOpp = makeOpportunity('Mixed - open', PROSPECTING,
            Date.newInstance(2025, 7, 5), openAcct.Id);
        openOpp.NextStep = 'Keep open next step';
        Opportunity lostOpp = makeOpportunity('Mixed - lost', LOST,
            Date.newInstance(2025, 7, 6), null);
        lostOpp.NextStep = 'Keep lost next step';
        Opportunity wonOpp = makeOpportunity('Mixed - won', WON,
            Date.newInstance(2025, 7, 4), wonAcct.Id);
        wonOpp.NextStep = 'To be replaced';

        // The won record deliberately is not the first one in the batch.
        insert new List<Opportunity>{ openOpp, lostOpp, wonOpp };

        System.assertEquals(HANDOVER, nextStepOf(wonOpp.Id), 'The won record must be handed over.');
        System.assertEquals('Keep open next step', nextStepOf(openOpp.Id),
            'A prospecting record in the same batch must be untouched.');
        System.assertEquals('Keep lost next step', nextStepOf(lostOpp.Id),
            'A lost record in the same batch must be untouched.');

        List<Task> tasks = tasksFor(new Set<Id>{ wonOpp.Id, openOpp.Id, lostOpp.Id });
        System.assertEquals(1, tasks.size(), 'Only the Closed Won record gets a kick-off task.');
        System.assertEquals(wonOpp.Id, tasks[0].WhatId, 'The task must belong to the won record.');
        System.assertEquals(HIGH, tasks[0].Priority, 'The task priority must be High.');
        System.assertEquals(Date.newInstance(2025, 7, 11), tasks[0].ActivityDate,
            'ActivityDate must be CloseDate + 7 days.');

        System.assertEquals(HOT, ratingOf(wonAcct.Id),
            'The account of the won record must be re-rated Hot.');
        System.assertEquals(WARM, ratingOf(openAcct.Id),
            'The account of a record that is not won must not be re-rated.');
    }

    @IsTest
    static void mixedUpdateOnlyHandoversTheNewlyWonRecord() {
        Account warmAcct = makeAccount(WARM);
        Account coldAcct = makeAccount(COLD);
        insert new List<Account>{ warmAcct, coldAcct };

        Opportunity staysOpen = makeOpportunity('Update - open', PROSPECTING,
            Date.newInstance(2025, 8, 3), coldAcct.Id);
        staysOpen.NextStep = 'Open next step';
        Opportunity becomesWon = makeOpportunity('Update - becomes won', PROSPECTING,
            Date.newInstance(2025, 8, 1), warmAcct.Id);
        becomesWon.NextStep = 'Before handover';
        Opportunity wasWon = makeOpportunity('Update - already won', WON,
            Date.newInstance(2025, 8, 2), null);
        wasWon.NextStep = 'Already handed over';

        insert new List<Opportunity>{ staysOpen, wasWon, becomesWon };
        System.assertEquals(1, tasksFor(new Set<Id>{ wasWon.Id }).size(),
            'Sanity check: the already-won record created one task on insert.');
        System.assertEquals(0, tasksFor(new Set<Id>{ staysOpen.Id, becomesWon.Id }).size(),
            'Sanity check: nothing was created for the records that are not won.');

        staysOpen.NextStep = 'Open next step v2';
        wasWon.NextStep = 'Handover cancelled';
        becomesWon.StageName = WON;

        // The newly won record deliberately is not the first one in the batch.
        update new List<Opportunity>{ staysOpen, becomesWon, wasWon };

        System.assertEquals(HANDOVER, nextStepOf(becomesWon.Id),
            'The record that just became Closed Won must get the handover text.');
        System.assertEquals('Handover cancelled', nextStepOf(wasWon.Id),
            'A record that was already won must keep the NextStep the user entered.');
        System.assertEquals('Open next step v2', nextStepOf(staysOpen.Id),
            'A record that stays open must keep the NextStep the user entered.');

        System.assertEquals(1, tasksFor(new Set<Id>{ becomesWon.Id }).size(),
            'The newly won record must get exactly one task.');
        System.assertEquals(1, tasksFor(new Set<Id>{ wasWon.Id }).size(),
            'The already-won record must not get a second task.');
        System.assertEquals(0, tasksFor(new Set<Id>{ staysOpen.Id }).size(),
            'The record that stays open must not get a task.');
        System.assertEquals(2, tasksFor(new Set<Id>{ staysOpen.Id, becomesWon.Id, wasWon.Id }).size(),
            'Exactly one new task may be created for the whole batch (plus the one from before).');

        System.assertEquals(HOT, ratingOf(warmAcct.Id),
            'The account of the newly won record must be re-rated Hot.');
        System.assertEquals(COLD, ratingOf(coldAcct.Id),
            'The account of the record that stays open must not be re-rated.');
    }

    /* ------------------------------------------------------------------ */
    /* already-hot account is not updated again                           */
    /* ------------------------------------------------------------------ */

    @IsTest
    static void alreadyHotAccountIsNotUpdatedAgain() {
        Account hotAcct = makeAccount(HOT);
        insert hotAcct;

        Opportunity opp = makeOpportunity('Won with an already hot account', PROSPECTING,
            Date.newInstance(2025, 3, 1), hotAcct.Id);
        insert opp;
        System.assertEquals(0, tasksFor(new Set<Id>{ opp.Id }).size(), 'Sanity check: not won yet.');
        System.assertEquals(HOT, ratingOf(hotAcct.Id), 'Sanity check: the account already is Hot.');

        Integer dmlBefore = Limits.getDmlStatements();
        Integer soqlBefore = Limits.getQueries();

        opp.StageName = WON;
        update opp;

        Integer dmlUsed = Limits.getDmlStatements() - dmlBefore;
        Integer soqlUsed = Limits.getQueries() - soqlBefore;

        // Expected: the opportunity update itself + the single task insert.
        System.assert(dmlUsed <= 2,
            'Expected only the Opportunity update and the Task insert; an account already rated Hot '
            + 'must not be updated again. DML statements used: ' + dmlUsed + '.');
        System.assert(soqlUsed <= 1,
            'Expected at most one SOQL query for this trigger execution. SOQL queries used: '
            + soqlUsed + '.');

        List<Task> tasks = tasksFor(new Set<Id>{ opp.Id });
        System.assertEquals(1, tasks.size(), 'Exactly one kick-off task must be created.');
        System.assertEquals(KICK_OFF, tasks[0].Subject, 'The task subject must be "Customer kick-off".');
        System.assertEquals(HIGH, tasks[0].Priority, 'The task priority must be High.');
        System.assertEquals(HOT, ratingOf(hotAcct.Id), 'The rating must stay Hot.');
        System.assertEquals(HANDOVER, nextStepOf(opp.Id), 'NextStep must be set to the handover text.');
