public class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = (accountIds == null) ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer first, before any work, so every run is logged
        // and retried - even when the work below blows up.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(Id = accountId, Description = 'Synced to ERP'));
        }

        if (!accountsToUpdate.isEmpty()) {
            // All-or-nothing DML: if any account cannot be saved, the whole
            // statement fails, no record is changed, the exception propagates
            // out of the job (it is deliberately not caught) and the transaction
            // is rolled back.
            update accountsToUpdate;
        }
    }
}
