public class ErpSyncFinalizer implements Finalizer {

    private static final String JOB_NAME = 'ErpAccountSyncJob';
    private static final Integer MAX_ERROR_LENGTH = 255;
    private static final Integer MAX_ATTEMPTS = 3;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = (accountIds == null) ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        Exception jobException = (context == null) ? null : context.getException();
        Boolean failed = (jobException != null);

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Attempt__c = attempt,
            Status__c = failed ? 'Failed' : 'Success'
        );

        if (failed) {
            String message = jobException.getMessage();
            if (message != null && message.length() > MAX_ERROR_LENGTH) {
                message = message.substring(0, MAX_ERROR_LENGTH);
            }
            jobLog.Error__c = message;
        }

        insert jobLog;

        // Retry only the first two failures; after the third failed attempt stop.
        if (failed && attempt != null && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
