public class Opportunities extends fflib_SObjectDomain
{
	// Ensures startFulfilment is invoked at most once per trigger invocation
	private static Boolean fulfilmentStarted = false;

	public Opportunities(List<Opportunity> sObjectList)
	{
		super(sObjectList);
	}

	public Opportunities()
	{
		super();
	}

	public override void onAfterInsert(List<SObject> records)
	{
		startFulfilmentFor(QualifyingIds(records, null));
	}

	public override void onAfterUpdate(List<SObject> records, Map<Id, SObject> oldRecordsMap)
	{
		startFulfilmentFor(QualifyingIds(records, oldRecordsMap));
	}

	private static Set<Id> QualifyingIds(List<SObject> records, Map<Id, SObject> oldRecordsMap)
	{
		Set<Id> qualifyingIds = new Set<Id>();
		for (SObject record : records)
		{
			Opportunity opportunity = (Opportunity) record;
			if (opportunity.StageName != 'Closed Won')
			{
				continue;
			}
			if (oldRecordsMap != null)
			{
				Opportunity oldOpportunity = (Opportunity) oldRecordsMap.get(opportunity.Id);
				// Already Closed Won before the update: does not qualify again
				if (oldOpportunity != null && oldOpportunity.StageName == 'Closed Won')
				{
					continue;
				}
			}
			qualifyingIds.add(opportunity.Id);
		}
		return qualifyingIds;
	}

	private static void startFulfilmentFor(Set<Id> opportunityIds)
	{
		if (fulfilmentStarted || opportunityIds == null || opportunityIds.isEmpty())
		{
			return;
		}
		fulfilmentStarted = true;
		IOpportunityFulfilmentService service =
			(IOpportunityFulfilmentService) Application.Service.newInstance(
				IOpportunityFulfilmentService.class
			);
		service.startFulfilment(opportunityIds);
	}

	public class Constructor implements fflib_SObjectDomain.IConstructable
	{
		public fflib_SObjectDomain construct(List<SObject> sObjectList)
		{
			return new Opportunities(sObjectList);
		}
	}
}
