public class Opportunities extends fflib_SObjectDomain
{
	private static final String AMOUNT_FIELD = 'Amount';
	private static final String STAGE_CLOSED_WON = 'Closed Won';

	private static final String MSG_AMOUNT_NEGATIVE = 'Amount cannot be negative.';
	private static final String MSG_AMOUNT_CHANGED_ON_WON = 'Amount cannot change on a won opportunity.';

	public Opportunities(List<Opportunity> records)
	{
		super(records);
	}

	/**
	 * Validation hook invoked for records being inserted.
	 *
	 * The Id check keeps this rule scoped to the insert context: records that
	 * already carry an Id are part of an update and are validated by
	 * onValidate(Map<Id, SObject>), so the rule is never applied twice to the
	 * same record, whichever hooks the framework invokes for a given event.
	 */
	public override void onValidate()
	{
		for (Opportunity record : (List<Opportunity>) Records)
		{
			if (record.Id == null && isNegative(record.Amount))
			{
				error(MSG_AMOUNT_NEGATIVE, record, AMOUNT_FIELD);
			}
		}
	}

	/**
	 * Validation hook invoked for records being updated.
	 *
	 * @param existingRecords The records as they were before the update, keyed by Id.
	 */
	public override void onValidate(Map<Id, SObject> existingRecords)
	{
		for (Opportunity record : (List<Opportunity>) Records)
		{
			// Insert context is handled by onValidate().
			if (record.Id == null)
			{
				continue;
			}

			// Rule 1: Amount must not be negative on update either.
			if (isNegative(record.Amount))
			{
				error(MSG_AMOUNT_NEGATIVE, record, AMOUNT_FIELD);
			}

			if (existingRecords == null)
			{
				continue;
			}

			Opportunity existing = (Opportunity) existingRecords.get(record.Id);
			if (existing == null)
			{
				continue;
			}

			// Rule 2: an opportunity that was already Closed Won before this update
			// cannot have its Amount changed. An opportunity that only becomes
			// Closed Won in this very update is allowed to change its Amount,
			// because the stage of the record before the update was not Closed Won.
			if (existing.StageName == STAGE_CLOSED_WON && record.Amount != existing.Amount)
			{
				error(MSG_AMOUNT_CHANGED_ON_WON, record, AMOUNT_FIELD);
			}
		}
	}

	private static Boolean isNegative(Decimal amount)
	{
		return amount != null && amount < 0;
	}

	public class Constructor implements fflib_SObjectDomain.IConstructable
	{
		public fflib_SObjectDomain construct(List<SObject> sObjectList)
		{
			return new Opportunities((List<Opportunity>) sObjectList);
		}
	}
}
