        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // newQueryFactory(false) keeps the selector's field list and CRUD/FLS security
        // settings, but suppresses the selector's default ordering (Name) so that this
        // method's own ordering is the only one applied.
        fflib_QueryFactory queryFactory = newQueryFactory(false);

        // Standard selector fields plus the parent account's Name.
        queryFactory.selectField('Account.Name');

        // Open opportunities belonging to the given accounts.
        queryFactory.setCondition('IsClosed = false AND AccountId IN :accountIds');

        // Highest Amount first (records without an Amount sort last for a descending
        // ordering), equal amounts ordered by earliest CloseDate first.
        queryFactory.addOrdering('Amount', fflib_QueryFactory.SortOrder.DESCENDING);
        queryFactory.addOrdering('CloseDate', fflib_QueryFactory.SortOrder.ASCENDING);

        if (maxRecords != null) {
            queryFactory.setLimit(maxRecords);
        }

        return (List<Opportunity>) Database.query(queryFactory.toSOQL());
    }
}
