import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

// Fields requested from Lightning Data Service.
const FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    /**
     * The record Id provided by the record page.
     * Declared as a public property so the wire adapter configuration is
     * re-evaluated automatically whenever the value changes (for example a
     * console tab that is reused for a different Account).
     */
    @api recordId;

    /**
     * getRecord wire adapter. `$recordId` makes the wire re-run when the
     * property changes. `fields` makes all four requested fields mandatory
     * for the adapter configuration.
     */
    @wire(getRecord, {
        recordId: '$recordId',
        fields: FIELDS
    })
    account;

    /**
     * True while the record has neither loaded nor returned an error.
     */
    get isLoading() {
        return !this.account || (!this.account.data && !this.account.error);
    }

    get hasData() {
        return !!(this.account && this.account.data);
    }

    get hasError() {
        return !!(this.account && this.account.error);
    }

    get name() {
        return this.hasData ? this.account.data.fields.Name.value : null;
    }

    get industry() {
        return this.hasData ? this.account.data.fields.Industry.value : null;
    }

    get showIndustry() {
        const value = this.industry;
        return value !== undefined && value !== null && value !== '';
    }

    get annualRevenue() {
        return this.hasData ? this.account.data.fields.AnnualRevenue.value : null;
    }

    get ownerName() {
        if (!this.hasData) {
            return null;
        }
        const ownerField = this.account.data.fields.Owner;
        if (!ownerField) {
            return null;
        }
        // Preferred: the display value for the lookup (the owner's Name).
        if (ownerField.displayValue) {
            return ownerField.displayValue;
        }
        // Fallback: nested Account.Owner.Name requested through the wire.
        const ownerValue = ownerField.value;
        if (ownerValue && ownerValue.fields && ownerValue.fields.Name) {
            return ownerValue.fields.Name.value;
        }
        return null;
    }

    get errorMessage() {
        return this.hasError ? this.account.error.body.message : null;
    }
}
