```javascript
/**
 * collapsibleSection - a reusable WAI-ARIA disclosure section.
 *
 * Usage:
 *   <c-collapsible-section>
 *       <span slot="title">Billing details</span>
 *       <p>Any body content…</p>
 *   </c-collapsible-section>
 *
 * - The named `title` slot renders inside the native toggle button.
 * - The default (unnamed) slot renders inside the section body.
 * - The section starts collapsed.
 * - The body element is always present in the DOM so `aria-controls` always
 *   resolves; while collapsed it carries the `hidden` attribute, and while
 *   expanded it does not.
 */
import { LightningElement } from 'lwc';

/**
 * Module-scoped counter so every instance rendered on the page gets its own
 * unique body id (an `id` used by `aria-controls` must be unique in the
 * document, and multiple sections can be placed on the same page).
 * @type {number}
 */
let instanceCounter = 0;

export default class CollapsibleSection extends LightningElement {
    /**
     * Whether the section body is currently visible. All class fields are
     * reactive in LWC, so mutating this re-renders the component.
     * @type {boolean}
     */
    isExpanded = false;

    /**
     * Stable, unique id for the section body element, referenced by the
     * toggle button's `aria-controls`.
     * @type {string}
     */
    bodyId = `collapsible-section-body-${instanceCounter++}`;

    /**
     * `aria-expanded` must be the literal string "true" or "false".
     * @returns {string}
     */
    get ariaExpanded() {
        return this.isExpanded ? 'true' : 'false';
    }

    /**
     * @returns {boolean} true while the section body should be hidden.
     */
    get isCollapsed() {
        return !this.isExpanded;
    }

    /**
     * Toggles the disclosure. The native `<button>` already provides Enter and
     * Space activation, so no additional keyboard handling is needed to satisfy
     * the WAI-ARIA disclosure pattern.
     */
    handleToggle() {
        this.isExpanded = !this.isExpanded;
    }

    /**
     * Keeps the `hidden` attribute on the section body in sync with the
     * expanded state.
     *
     * `hidden` is an HTML boolean attribute: only its presence matters, so
     * `hidden="false"` would still hide the element. Rather than relying on
     * the stringified value of a bound expression, the attribute is added
     * (`hidden=""`) while collapsed and removed entirely while expanded.
     * LWC only patches attributes that are bound in the template, so this
     * value is stable across re-renders and the body always stays in the DOM.
     */
    renderedCallback() {
        const body = this.template.querySelector('.section-body');
        if (!body) {
            return;
        }
        if (this.isCollapsed) {
            body.setAttribute('hidden', '');
        } else {
            body.removeAttribute('hidden');
        }
    }
}
