import { LightningElement, api, wire } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { updateRecord, refreshApex } from 'lightning/uiRecordApi';
import getContacts from '@salesforce/apex/ContactController.getContacts';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    columns = COLUMNS;
    draftValues = [];
    wiredContacts;

    // Reactive wire: re-runs whenever recordId changes/is available.
    @wire(getContacts, { accountId: '$recordId' })
    contactWiring(result) {
        this.wiredContacts = result;
    }

    // The wired contacts used as the datatable data.
    get contacts() {
        return this.wiredContacts && this.wiredContacts.data
            ? this.wiredContacts.data
            : [];
    }

    handleSave(event) {
        const drafts = event.detail.draftValues;

        // One updateRecord call per draft row, fired in parallel; each promise is
        // settled locally so Promise.all waits for every request to complete.
        const requests = drafts.map((draft) =>
            updateRecord({ fields: { ...draft } })
                .then(() => ({ ok: true }))
                .catch((error) => ({ ok: false, error }))
        );

        Promise.all(requests)
            .then((results) => {
                const failure = results.find((result) => !result.ok);

                if (failure) {
                    // Failure path: error toast only - no refresh, no success toast.
                    this.dispatchEvent(
                        new ShowToastEvent({
                            variant: 'error',
                            title: 'Could not save contacts',
                            message:
                                failure.error && failure.error.body
                                    ? failure.error.body.message
                                    : 'An unexpected error occurred.'
                        })
                    );
                    return;
                }

                // Success path.
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Contacts updated'
                    })
                );
                this.draftValues = [];
                return refreshApex(this.wiredContacts);
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Could not save contacts',
                        message:
                            error && error.body
                                ? error.body.message
                                : 'An unexpected error occurred.'
                    })
                );
            });
    }
}
