import { LightningElement, wire } from 'lwc';
import {
    MessageContext,
    APPLICATION_SCOPE,
    subscribe,
    unsubscribe,
    publish
} from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    // The Id of the currently selected account, or null/undefined when none is selected.
    selectedRecordId;

    // Holds the active subscription so we never create more than one.
    subscription;

    // The message context is provided by the @wire service and is required by
    // subscribe(), unsubscribe() and publish().
    @wire(MessageContext)
    messageContext;

    connectedCallback() {
        // The publisher lives in the utility bar (application scope), so this
        // component must subscribe with APPLICATION_SCOPE to receive its messages.
        this.subscribeToMessageChannel();
    }

    disconnectedCallback() {
        // Clean up when the component leaves the page (e.g. a tab is closed),
        // so a later re-insert starts from a clean state.
        this.unsubscribeFromMessageChannel();
    }

    subscribeToMessageChannel() {
        if (this.subscription) {
            // Never hold more than one subscription.
            return;
        }

        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeFromMessageChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = undefined;
        }
    }

    handleMessage(message) {
        // A message without a recordId (including the clear payload
        // { recordId: null }) resets the panel to its placeholder state.
        this.selectedRecordId =
            message && message.recordId ? message.recordId : null;
    }

    handleClear() {
        // Publish on the same channel so every listening component clears
        // its selection; this panel receives its own message as well.
        publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
    }
}
