import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    /** The Account record Id supplied by the record page. */
    _recordId;
    _connected = false;
    _loaded = false;

    /** Opportunities returned by Apex. */
    opportunities = [];

    /** True while an Apex call is in flight. */
    isLoading = false;

    /** Error object from the last failed Apex call. */
    error;

    /**
     * recordId is normally assigned before the element is inserted, in which
     * case connectedCallback issues the single initial call. If it arrives
     * after insertion instead, the setter issues that same single call.
     * In neither ordering is the method called twice.
     */
    @api
    set recordId(value) {
        const previous = this._recordId;
        this._recordId = value;
        if (this._connected && value && value !== previous && !this.isLoading) {
            this.load();
        }
    }
    get recordId() {
        return this._recordId;
    }

    connectedCallback() {
        this._connected = true;
        if (this._recordId) {
            this.load();
        }
    }

    disconnectedCallback() {
        this._connected = false;
    }

    /** Imperatively call Apex; the spinner is shown while the call runs. */
    async load() {
        if (this.isLoading) {
            return;
        }
        this.isLoading = true;
        this.error = undefined;
        try {
            const results = await getOpenOpportunities({ accountId: this._recordId });
            this.opportunities = Array.isArray(results) ? results : [];
            this._loaded = true;
        } catch (err) {
            this.opportunities = [];
            this._loaded = false;
            // Normalise so the template never dereferences a missing property.
            this.error =
                err && typeof err === 'object'
                    ? err
                    : {
                          body: {
                              message:
                                  err === undefined || err === null
                                      ? 'An unexpected error occurred.'
                                      : String(err)
                          }
                      };
        } finally {
            this.isLoading = false;
        }
    }

    /** Retry a failed call; the spinner is shown again while it runs. */
    handleRetry() {
        this.load();
    }

    /* ---- mutually exclusive view states ---- */

    get showSpinner() {
        return this.isLoading === true;
    }

    get showError() {
        return (
            this.isLoading === false &&
            this.error !== undefined &&
            this.error !== null
        );
    }

    get showList() {
        return (
            this.isLoading === false &&
            !this.showError &&
            this._loaded === true &&
            Array.isArray(this.opportunities) &&
            this.opportunities.length > 0
        );
    }

    get showEmpty() {
        return (
            this.isLoading === false &&
            !this.showError &&
            this._loaded === true &&
            (!Array.isArray(this.opportunities) || this.opportunities.length === 0)
        );
    }

    /** Safe access to error.body.message for any error shape. */
    get errorMessage() {
        const err = this.error;
        if (err === undefined || err === null) {
            return '';
        }
        if (typeof err === 'string') {
            return err;
        }
        if (err.body && typeof err.body.message === 'string') {
            return err.body.message;
        }
        if (typeof err.message === 'string') {
            return err.message;
        }
        try {
            return JSON.stringify(err);
        } catch (e) {
            return String(err);
        }
    }
}
