/**
 * Keeps the "current employer" supplied by the donor web form in sync with NPSP.
 *
 * For every Contact in the map the service guarantees that, after the call:
 *   - a Current, primary affiliation to the Organization Account exists (created or repaired);
 *   - Contact.npsp__Primary_Affiliation__c points to that Organization Account;
 *   - the previous primary employer ends up Former, non primary, with an end date of today.
 *     NPSP applies this itself as soon as a new primary affiliation is written (its standard
 *     mechanism); the demotion is written in the very same statement as well, so the resulting
 *     data is identical whichever of the two performs it;
 *   - the Contact keeps its Household Account (Contact.AccountId is never touched);
 *   - nothing is written at all when the organization already is the primary affiliation.
 *
 * Bulk safe: a single call with 200 Contacts uses 2 SOQL queries and at most 2 DML statements
 * of its own.
 */
public with sharing class EmployerService {

    /** NPSP affiliation status values used by this org. */
    private static final String STATUS_CURRENT = 'Current';
    private static final String STATUS_FORMER = 'Former';

    /**
     * Sets the current employer (Organization Account) for each Contact.
     *
     * @param employerByContactId map of Contact Id -> Organization Account Id. Null or empty
     *        entries are ignored; a null/empty map does nothing.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        // ---------------------------------------------------------------- guard / sanitize
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Map<Id, Id> employerByContact = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (contactId != null && employerId != null) {
                employerByContact.put(contactId, employerId);
            }
        }
        if (employerByContact.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContact.keySet();

        // -------------------------------------------------------------- SOQL 1: affiliations
        // Affiliations that already exist for the affected Contacts are collected in one pass:
        //   - the affiliation with the employer we are about to set (best candidate kept),
        //   - every other primary affiliation (the previous primary employer).
        Map<Id, npe5__Affiliation__c> employerAffiliationByContact =
            new Map<Id, npe5__Affiliation__c>();
        List<npe5__Affiliation__c> otherPrimaryAffiliations = new List<npe5__Affiliation__c>();

        for (npe5__Affiliation__c affiliation : [
                SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Primary__c,
                       npe5__Status__c, npe5__StartDate__c, npe5__EndDate__c, npe5__Role__c
                FROM npe5__Affiliation__c
                WHERE npe5__Contact__c IN :contactIds ]) {

            if (affiliation.npe5__Organization__c ==
                    employerByContact.get(affiliation.npe5__Contact__c)) {
                // Affiliation with the incoming employer - keep the "best" duplicate, if any.
                npe5__Affiliation__c candidate =
                    employerAffiliationByContact.get(affiliation.npe5__Contact__c);
                if (candidate == null
                        || (!isCurrentAndPrimary(candidate) && isCurrentAndPrimary(affiliation))) {
                    employerAffiliationByContact.put(affiliation.npe5__Contact__c, affiliation);
                }
            } else if (affiliation.npe5__Primary__c == true) {
                otherPrimaryAffiliations.add(affiliation);
            }
        }

        // --------------------------------------------------------------- SOQL 2: the contacts
        // The Contact's primary affiliation lookup, so that only contacts that really need it
        // are written to.
        Map<Id, Contact> contactsById = new Map<Id, Contact>();
        for (Contact contactRecord : [
                SELECT Id, npsp__Primary_Affiliation__c
                FROM Contact
                WHERE Id IN :contactIds ]) {
            contactsById.put(contactRecord.Id, contactRecord);
        }

        Date today = Date.today();
        List<npe5__Affiliation__c> affiliationsToUpsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();
        Set<Id> processedContactIds = new Set<Id>();

        // ------------------------------------- pass 1: affiliation + lookup for the employer
        for (Id contactId : contactIds) {
            Contact contactRecord = contactsById.get(contactId);
            if (contactRecord == null) {
                continue;                       // unknown or deleted Contact - nothing to do
            }
            processedContactIds.add(contactId);

            Id employerId = employerByContact.get(contactId);
            npe5__Affiliation__c employerAffiliation =
                employerAffiliationByContact.get(contactId);

            if (employerAffiliation == null) {
                // No affiliation yet -> create a new Current, primary one (NPSP will demote
                // the previous primary employer for us).
                affiliationsToUpsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = employerId,
                    npe5__Status__c = STATUS_CURRENT,
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today));
            } else if (!isCurrentAndPrimary(employerAffiliation)) {
                // Affiliation already exists (e.g. Former) -> repair it instead of inserting
                // a duplicate.
                employerAffiliation.npe5__Primary__c = true;
                employerAffiliation.npe5__Status__c = STATUS_CURRENT;
                employerAffiliation.npe5__EndDate__c = null;
                if (employerAffiliation.npe5__StartDate__c == null) {
                    employerAffiliation.npe5__StartDate__c = today;
                }
                affiliationsToUpsert.add(employerAffiliation);
            }
            // else: already the Current primary affiliation -> no affiliation change at all.

            // Point the Contact's primary affiliation lookup at the employer (no-op when it
            // already matches, which keeps the "nothing changes" case DML free).
            if (contactRecord.npsp__Primary_Affiliation__c != employerId) {
                contactRecord.npsp__Primary_Affiliation__c = employerId;
                contactsToUpdate.add(contactRecord);
            }
        }

        // --------------------------------- pass 2: demote the previous primary employer(s)
        // Written together with the new primary affiliation (single DML statement); NPSP applies
        // exactly the same values through its standard mechanism, so the outcome is idempotent.
        for (npe5__Affiliation__c affiliation : otherPrimaryAffiliations) {
            if (!processedContactIds.contains(affiliation.npe5__Contact__c)) {
                continue;                       // Contact was not processed - leave it alone
            }
            affiliation.npe5__Primary__c = false;
            affiliation.npe5__Status__c = STATUS_FORMER;
            affiliation.npe5__EndDate__c = today;
            affiliationsToUpsert.add(affiliation);
        }

        // ------------------------------------------------------------------ DML (max. 2)
        // DML 1: inserts and updates of affiliations in one statement.
        if (!affiliationsToUpsert.isEmpty()) {
            upsert affiliationsToUpsert;
        }
        // DML 2: primary affiliation lookup on the Contacts.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    /** True when the affiliation is already usable as the Contact's primary affiliation. */
    private static Boolean isCurrentAndPrimary(npe5__Affiliation__c affiliation) {
        return affiliation.npe5__Primary__c == true
            && affiliation.npe5__Status__c == STATUS_CURRENT
            && affiliation.npe5__EndDate__c == null;
    }
}
