/**
 * NPSP Table-Driven Trigger Management (TDTM) handler that opens a follow-up
 * task for every newly closed major gift.
 *
 * Admin registration (NPSP Settings > Trigger Configuration):
 *   Class          : OPP_MajorGiftFollowUp_TDTM
 *   Object         : Opportunity
 *   Trigger Action : AfterInsert;AfterUpdate
 *   Load Order     : 5
 *   Asynchronous   : No
 *
 * There is intentionally no Apex trigger in this package: NPSP's TDTM
 * dispatcher is the only caller, so deactivating the Trigger Handler record
 * switches this automation off for the whole org.
 *
 * Limits honoured by this handler (whole batch, one transaction):
 *   - SOQL queries   : at most 1
 *   - DML statements : at most 1 (one bulk insert of all Tasks)
 */
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;
    private static final Integer FOLLOW_UP_DAYS = 3;
    private static final String FOLLOW_UP_SUBJECT = 'Major gift thank-you call';
    private static final String FOLLOW_UP_PRIORITY = 'High';
    private static final String FOLLOW_UP_STATUS = 'Not Started';
    private static final String CLOSED_WON_STAGE = 'Closed Won';

    /**
     * Entry point invoked by NPSP's TDTM dispatcher for the registered
     * AfterInsert / AfterUpdate actions on Opportunity.
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        // --- Guard rails: only handle the events we were registered for ----
        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }
        if (objResult != null && objResult.getSObjectType() != Opportunity.SObjectType) {
            return dmlWrapper;
        }
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
                && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);

        List<Opportunity> newOpps = new List<Opportunity>();
        for (SObject record : newlist) {
            if (record != null) {
                newOpps.add((Opportunity) record);
            }
        }
        if (newOpps.isEmpty()) {
            return dmlWrapper;
        }

        // "old" rows are null on insert.
        List<Opportunity> oldOpps = new List<Opportunity>();
        if (!isInsert && oldlist != null) {
            for (SObject record : oldlist) {
                if (record != null) {
                    oldOpps.add((Opportunity) record);
                }
            }
        }

        // Index the pre-update values (used when the two lists are not aligned
        // by position) so an opportunity that already qualified never gets a
        // second follow-up task.
        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        for (Opportunity oldOpp : oldOpps) {
            if (oldOpp.Id != null) {
                oldOppsById.put(oldOpp.Id, oldOpp);
            }
        }

        // At most ONE SOQL query for the entire batch. It is only used to
        // back-fill fields that are not populated on the records handed to the
        // handler; values already present on the records always win.
        Map<Id, Opportunity> storedById = queryStoredValues(newOpps);

        List<Task> followUps = new List<Task>();

        for (Integer index = 0; index < newOpps.size(); index++) {
            Opportunity newOpp = newOpps[index];
            Opportunity stored = (newOpp.Id != null) ? storedById.get(newOpp.Id) : null;

            // (1) Must be a major gift right now: Closed Won + Amount >= 5,000.
            if (!isMajorGift(newOpp, stored)) {
                continue;
            }

            // (2) On update it must NOT already have been a major gift before,
            //     otherwise this is an edit of a gift that already qualified.
            Opportunity oldOpp = null;
            if (!isInsert) {
                if (oldOpps.size() == newOpps.size()) {
                    oldOpp = oldOpps[index];
                } else if (newOpp.Id != null) {
                    oldOpp = oldOppsById.get(newOpp.Id);
                }
            }
            if (isMajorGift(oldOpp, null)) {
                continue;
            }

            // Resolve the fields needed on the Task (record value first,
            // stored value as fallback).
            Id primaryContactId = newOpp.npsp__Primary_Contact__c;
            if (primaryContactId == null && stored != null) {
                primaryContactId = stored.npsp__Primary_Contact__c;
            }

            Id ownerId = newOpp.OwnerId;
            if (ownerId == null && stored != null) {
                ownerId = stored.OwnerId;
            }

            Date closeDate = newOpp.CloseDate;
            if (closeDate == null && stored != null) {
                closeDate = stored.CloseDate;
            }

            Task followUp = new Task();
            followUp.Subject = FOLLOW_UP_SUBJECT;
            followUp.Priority = FOLLOW_UP_PRIORITY;
            followUp.Status = FOLLOW_UP_STATUS;
            followUp.WhatId = newOpp.Id;
            followUp.WhoId = primaryContactId;                 // may be null
            followUp.OwnerId = ownerId;                        // opportunity owner
            followUp.ActivityDate = (closeDate == null)
                ? null
                : closeDate.addDays(FOLLOW_UP_DAYS);           // CloseDate + 3 days
            followUps.add(followUp);
        }

        // --- ONE bulk DML statement for the whole trigger batch -----------
        if (!followUps.isEmpty()) {
            insert followUps;
        }

        return dmlWrapper;
    }

    /**
     * A major gift is an opportunity that is Closed Won and has an Amount of at
     * least 5,000. Null-safe: a record that is missing a value simply does not
     * qualify.
     */
    private static Boolean isMajorGift(Opportunity opp, Opportunity stored) {
        if (opp == null && stored == null) {
            return false;
        }

        Decimal amount = null;
        if (opp != null && opp.Amount != null) {
            amount = opp.Amount;
        } else if (stored != null) {
            amount = stored.Amount;
        }

        if (amount == null || amount < MAJOR_GIFT_AMOUNT) {
            return false;
        }

        return isClosedWon(opp, stored);
    }

    /**
     * "Closed Won" is recognised either from the standard IsWon flag or from
     * the stage label, so customised stage names that are flagged as won still
     * count.
     */
    private static Boolean isClosedWon(Opportunity opp, Opportunity stored) {
        if (opp != null && opp.IsWon) {
            return true;
        }
        if (stored != null && stored.IsWon) {
            return true;
        }

        String stage = null;
        if (opp != null && String.isNotBlank(opp.StageName)) {
            stage = opp.StageName;
        } else if (stored != null) {
            stage = stored.StageName;
        }

        if (String.isBlank(stage)) {
            return false;
        }
        return CLOSED_WON_STAGE.equalsIgnoreCase(stage.trim());
    }

    /**
     * The single SOQL query allowed to this handler: loads the current values
     * of the opportunities in the batch so that any field that was not
     * populated on the in-memory records can still be resolved.
     */
    private static Map<Id, Opportunity> queryStoredValues(List<Opportunity> opps) {
        Set<Id> oppIds = new Set<Id>();
        for (Opportunity opp : opps) {
            if (opp.Id != null) {
                oppIds.add(opp.Id);
            }
        }
        if (oppIds.isEmpty()) {
            return new Map<Id, Opportunity>();
        }
        return new Map<Id, Opportunity>(
            [
                SELECT Id, Amount, StageName, IsWon, CloseDate, OwnerId, npsp__Primary_Contact__c
                FROM Opportunity
                WHERE Id IN :oppIds
            ]
        );
    }
}
