/**
 * Resolves record-level editability for the running user.
 *
 * The mass-edit screen passes a set of candidate record Ids (up to 2,000, possibly
 * spanning several sObjects) and must only be shown the ones the user is actually
 * allowed to edit. Ownership, sharing rules, the role hierarchy, "View All"/"Modify All"
 * and object/record permissions are all already baked into `UserRecordAccess.HasEditAccess`,
 * so this service simply reports what the platform says - it never re-implements the
 * sharing model (which would be both wrong and insecure).
 *
 * Notes:
 *  - `with sharing` keeps the class honest for any future SOQL/DML added to it; the
 *    UserRecordAccess query itself already resolves the *running* user's access.
 *  - Records for which the user has no access at all are omitted by the platform, and
 *    records the user can read but not edit come back with HasEditAccess = false;
 *    both cases are simply left out of the returned set.
 *  - The RecordId IN (...) clause is issued in bounded chunks so a full 2,000-record
 *    payload stays comfortably inside the 20-query budget for the transaction.
 */
public with sharing class RecordAccessService {

    /**
     * Number of record Ids sent per UserRecordAccess query.
     * 2,000 Ids / 100 per query = 20 queries exactly, which is the stated budget.
     */
    private static final Integer QUERY_CHUNK_SIZE = 100;

    /**
     * Returns the subset of `recordIds` the running user may edit.
     *
     * @param recordIds candidate record Ids (may be null, empty, unsorted and mixed-object)
     * @return the editable Ids, never null; empty when the input is null/empty
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {

        Set<Id> editable = new Set<Id>();

        // Defensive: never return null, and skip the query entirely when there is nothing to check.
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Strip nulls and duplicates defensively so the SOQL bind list is always clean.
        Set<Id> pending = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                pending.add(recordId);
            }
        }
        if (pending.isEmpty()) {
            return editable;
        }

        List<Id> ordered = new List<Id>(pending);
        ordered.sort(); // deterministic, stable chunking

        Id runningUserId = UserInfo.getUserId();
        Integer index = 0;
        Integer total = ordered.size();

        while (index < total) {

            Integer chunkEnd = Math.min(index + QUERY_CHUNK_SIZE, total);
            List<Id> chunk = new List<Id>();
            for (Integer i = index; i < chunkEnd; i++) {
                chunk.add(ordered[i]);
            }
            index = chunkEnd;

            // UserRecordAccess is queried per running user; Ids from any sObject may be
            // mixed in a single query. Rows are only returned where some access exists.
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess && access.RecordId != null) {
                    editable.add(access.RecordId);
                }
            }
        }

        // Only Ids that were actually reported as editable are returned; everything else
        // (no row, or HasEditAccess = false) is deliberately excluded.
        editable.retainAll(pending);
        return editable;
    }
}
