/**
 * Bulk-safe ownership reassignment for a book of business.
 *
 * Reassigns the supplied Accounts and every Contact that belongs to them to a single
 * new owner, using Trigger Actions Framework (TAF) 0.3.4 (unlocked package, no namespace).
 *
 * Trigger handling:
 *   - Account: the TAF *sObject* bypass (TriggerBase.bypass) is applied, so no Account
 *     trigger action registered in `sObject_Trigger_Setting__mdt` runs for this ownership
 *     change. It is restored in a `finally`, so Account automation behaves normally again
 *     whether this method succeeds or throws.
 *   - Contact: nothing is bypassed, so the Contact update executes every Contact trigger
 *     action normally. Accounts are updated first so that any Contact action that reads
 *     Account.OwnerId sees the new owner.
 *
 * Note: MetadataTriggerHandler.bypass(String) bypasses an individual *action* by name -
 * using it here with 'Account' would be wrong. The sObject-level bypass lives on TriggerBase.
 *
 * Limits (independent of volume, up to 200 accounts / any number of contacts):
 *   - 1 SOQL query (Contacts)
 *   - 2 DML statements (Accounts, Contacts), both all-or-none `update` statements.
 *
 * Sharing: deliberately `without sharing`. The caller has already authorised the account
 * set it passes in, and the contract requires *every* Contact of those Accounts to be
 * updated - enforcing record visibility here would silently skip contacts the running
 * user's role hierarchy or sharing model hides. Record-level access control belongs at
 * the entry point (UI, flow, API) that decides which books of business may be moved.
 */
public without sharing class AccountOwnershipService {

	/**
	 * Sets OwnerId on the given Accounts and on all Contacts of those Accounts.
	 *
	 * All-or-none: if any row fails, the whole method throws and the exception is allowed
	 * to propagate to the caller unchanged (no catch block swallows anything).
	 *
	 * @param accountIds  Accounts to move; empty/null is a no-op.
	 * @param newOwnerId  The receiving owner (user or queue) Id.
	 */
	public static void reassign(Set<Id> accountIds, Id newOwnerId) {
		if (accountIds == null || accountIds.isEmpty()) {
			return;
		}

		// Respect a bypass the caller may already have in place, so we never re-enable
		// Account automation that was intentionally disabled for this transaction.
		Boolean accountAlreadyBypassed = TriggerBase.isBypassed(Account.SObjectType);

		// Transaction bypass for the whole Account sObject: every registered Account
		// trigger action (territory recalculations, etc.) is skipped.
		TriggerBase.bypass(Account.SObjectType);
		try {
			// DML #1 - Account TAF automation is bypassed.
			update buildAccounts(accountIds, newOwnerId);

			// DML #2 - Contact TAF automation runs normally.
			List<Contact> contacts = buildContacts(accountIds, newOwnerId);
			if (!contacts.isEmpty()) {
				update contacts;
			}
		} finally {
			// Runs on success and on failure: Account automation must behave normally
			// for the rest of the transaction.
			if (!accountAlreadyBypassed) {
				TriggerBase.clearBypass(Account.SObjectType);
			}
		}
	}

	/**
	 * Sparse Account records - only OwnerId is written, so no other fields are touched.
	 * Built straight from the caller's Ids: no SOQL, no governor cost.
	 *
	 * NB: a new List(n) constructor would pre-size the list with n nulls; we always use
	 * the no-arg constructor and `add` so the list contains only real records.
	 */
	private static List<Account> buildAccounts(Set<Id> accountIds, Id newOwnerId) {
		List<Account> accounts = new List<Account>();
		for (Id accountId : accountIds) {
			accounts.add(new Account(Id = accountId, OwnerId = newOwnerId));
		}
		return accounts;
	}

	/**
	 * A single query returns the Contacts of all supplied Accounts, whatever the volume.
	 * Sparse Contact records - only OwnerId is written.
	 */
	private static List<Contact> buildContacts(Set<Id> accountIds, Id newOwnerId) {
		List<Contact> contacts = new List<Contact>();
		for (Contact existing : [
			SELECT Id
			FROM Contact
			WHERE AccountId IN :accountIds
		]) {
			contacts.add(new Contact(Id = existing.Id, OwnerId = newOwnerId));
		}
		return contacts;
	}
}
