public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
	private static final String TASK_SUBJECT = 'Amount changed';
	private static final String TASK_STATUS = 'Completed';

	/*
	 * Ids of Opportunities for which an 'Amount changed' Task has already been
	 * created during the current transaction.  The rounding action
	 * (TA_Opportunity_RoundAmount, Order 20) updates the same Opportunities again
	 * inside the same transaction, which re-enters every Opportunity after-update
	 * action.  Static state lives for the whole transaction, so this guarantees at
	 * most one audit Task per Opportunity per transaction while still allowing a
	 * later, genuinely independent Amount change to be recorded.
	 */
	private static Set<Id> alreadyLoggedOpportunityIds = new Set<Id>();

	public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
		List<Task> tasksToInsert = new List<Task>();
		Integer recordCount = triggerNew.size();

		for (Integer i = 0; i < recordCount; i++) {
			Opportunity newOpportunity = triggerNew[i];
			Opportunity oldOpportunity = triggerOld[i];

			// Already audited in this transaction (e.g. caused by the rounding re-entry).
			if (alreadyLoggedOpportunityIds.contains(newOpportunity.Id)) {
				continue;
			}

			// Only a real Amount change is audited; null-safe (null == null is true).
			if (newOpportunity.Amount == oldOpportunity.Amount) {
				continue;
			}

			alreadyLoggedOpportunityIds.add(newOpportunity.Id);
			tasksToInsert.add(
				new Task(
					WhatId = newOpportunity.Id,
					Subject = TASK_SUBJECT,
					Status = TASK_STATUS
				)
			);
		}

		// Single, bulk-safe DML statement per trigger execution (up to 200 rows).
		if (!tasksToInsert.isEmpty()) {
			insert tasksToInsert;
		}
	}
}
