/**
 * Shared parent-Account cache for the Contact before-insert trigger actions.
 *
 * The singleton getInstance() accessor guarantees that every action running in
 * the same trigger execution works from the same map, so the parent Accounts are
 * queried exactly once per trigger execution instead of once per action.
 */
public inherited sharing class TA_Contact_Queries {
	private static TA_Contact_Queries instance;

	/**
	 * Parent accounts of the Contacts in the current trigger execution,
	 * keyed by Account Id. Never null - starts empty so consumers are safe
	 * even if the Service action has not run yet.
	 */
	public Map<Id, Account> accountsById = new Map<Id, Account>();

	private TA_Contact_Queries() {
	}

	public static TA_Contact_Queries getInstance() {
		if (instance == null) {
			instance = new TA_Contact_Queries();
		}
		return instance;
	}

	/**
	 * Trigger action registered first (Order 1) on Contact before insert.
	 * The map is rebuilt on every trigger execution - never cached across
	 * executions - because later DML in the same transaction can involve
	 * other accounts. Bulk safe: one Set of Ids and one SOQL query,
	 * regardless of whether 1 or 200 Contacts are being inserted.
	 */
	public class Service implements TriggerAction.BeforeInsert {
		public void beforeInsert(List<SObject> triggerNew) {
			Set<Id> accountIds = new Set<Id>();
			for (SObject record : triggerNew) {
				Contact newContact = (Contact) record;
				if (newContact.AccountId != null) {
					accountIds.add(newContact.AccountId);
				}
			}
			getInstance().accountsById = new Map<Id, Account>(
				[
					SELECT
						Id,
						AccountSource,
						BillingStreet,
						BillingCity,
						BillingPostalCode,
						BillingCountry
					FROM Account
					WHERE Id IN :accountIds
				]
			);
		}
	}
}
