/**
 * Before insert: a new Contact that has an Account and a blank LeadSource
 * defaults to the parent Account's AccountSource. Contacts without an Account,
 * or that already have a LeadSource, are left untouched.
 * Performs no SOQL - it reads the Accounts loaded by TA_Contact_Queries.Service.
 */
public inherited sharing class TA_Contact_DefaultLeadSource
		implements TriggerAction.BeforeInsert {
	public void beforeInsert(List<SObject> triggerNew) {
		Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
		if (accountsById == null) {
			return;
		}
		for (SObject record : triggerNew) {
			Contact newContact = (Contact) record;
			if (newContact.AccountId == null || String.isNotBlank(newContact.LeadSource)) {
				continue;
			}
			Account parentAccount = accountsById.get(newContact.AccountId);
			if (parentAccount == null) {
				continue;
			}
			newContact.LeadSource = parentAccount.AccountSource;
		}
	}
}
